(
  'a1b2c3d4-0001-0001-0001-000000000001',
  'OutreachAI',
  'https://ui-avatars.com/api/?name=OutreachAI&background=3b82f6&color=fff&bold=true',
  'AI-powered sales email sequences that book more meetings.',
  'OutreachAI automates personalized cold email campaigns using AI to write, schedule, and optimize every message for your prospects.',
  'OutreachAI is the leading AI-powered sales engagement platform. Using advanced NLP and behavioral data, it crafts hyper-personalized email sequences that adapt based on prospect interactions — dramatically increasing reply rates and booked meetings.',
  'https://outreachai.example.com',
  ARRAY['Email Automation','Lead Generation','CRM Integration'],
  'sales',
  'Paid',
  3,
  4.8, 1240, true, 'active', true,
  '[{"title":"AI Sequence Builder","description":"Generate full multi-touch email sequences from a single prompt."},{"title":"Smart Send Time","description":"Sends at the exact time each prospect is most likely to open."},{"title":"CRM Sync","description":"Bi-directional sync with Salesforce, HubSpot, and Pipedrive."}]',
  to_jsonb(ARRAY['Dramatically reduces prospecting time','High deliverability rates','Easy CRM integration']),
  to_jsonb(ARRAY['Premium pricing','Learning curve for advanced sequences']),
  'B2B SDRs and Account Executives managing 100+ prospects per week.',
  '[{"step":1,"title":"Connect CRM","description":"Authorize OutreachAI to sync your contact data from Salesforce or HubSpot."},{"step":2,"title":"Define ICP","description":"Set your Ideal Customer Profile using firmographic and technographic filters."},{"step":3,"title":"Generate Sequence","description":"Use the AI Sequence Builder to create a 5-touch email campaign in under 5 minutes."},{"step":4,"title":"Launch & Monitor","description":"Activate the campaign and monitor open/reply rates in the live dashboard."}]',
  '{"metric":"15 hours/week saved","description":"Reduced manual prospecting from 20 hours to 5 hours per week across the entire SDR team.","author":"Sarah Jenkins","role":"VP of Sales, TechFlow"}'
),
(
  'a1b2c3d4-0002-0002-0002-000000000002',
  'CodeFlow',
  'https://ui-avatars.com/api/?name=CodeFlow&background=8b5cf6&color=fff&bold=true',
  'Context-aware AI code completion for every major IDE.',
  'CodeFlow provides intelligent, repository-aware code completions that understand your entire codebase — not just the current file.',
  'CodeFlow goes beyond simple autocomplete. Its context engine indexes your entire repository to provide suggestions that are aware of your architecture, naming conventions, and existing functions — dramatically reducing time spent writing boilerplate.',
  'https://codeflow.example.com',
  ARRAY['Code Completion','Developer Tools','IDE Integration'],
  'engineering',
  'Freemium',
  2,
  4.9, 850, true, 'active', true,
  '[{"title":"Repo-Wide Context","description":"Understands your full codebase, not just the open file."},{"title":"Multi-Language Support","description":"Works with 30+ programming languages."},{"title":"Test Generation","description":"Auto-generates unit tests for any function with a single shortcut."}]',
  to_jsonb(ARRAY['Extremely accurate suggestions','Massive time savings on boilerplate','Strong privacy mode']),
  to_jsonb(ARRAY['Resource-intensive on large repos','Free tier limited to 3 files']),
  'Engineering teams building complex, multi-file applications in any language.',
  '[{"step":1,"title":"Install Extension","description":"Install the CodeFlow extension from your IDE marketplace (VS Code, JetBrains, Neovim)."},{"step":2,"title":"Authenticate","description":"Sign in with GitHub or Google to activate your license."},{"step":3,"title":"Index Repository","description":"Run codeflow index in your terminal to build the context model for your repo."},{"step":4,"title":"Start Coding","description":"Accept suggestions with Tab or cycle through alternatives with Alt+]."}]',
  '{"metric":"10 hours/week saved","description":"Engineers report spending 10+ fewer hours per week on repetitive code, allowing them to focus on architecture.","author":"Michael Chen","role":"Senior DevOps, CloudScale"}'
),
(
  'a1b2c3d4-0003-0003-0003-000000000003',
  'TalentScout',
  'https://ui-avatars.com/api/?name=TalentScout&background=10b981&color=fff&bold=true',
  'Screen hundreds of resumes in minutes with AI-powered HR tools.',
  'TalentScout uses AI to score, rank, and summarize resumes so your HR team focuses only on the best candidates.',
  'TalentScout transforms the resume screening process. Upload a job description and hundreds of resumes — TalentScout scores each candidate against your requirements, flags red-flags, highlights top candidates, and drafts interview questions automatically.',
  'https://talentscout.example.com',
  ARRAY['Resume Screening','Candidate Ranking','HR Automation'],
  'hr',
  'Trial',
  5,
  4.6, 320, true, 'active', false,
  '[{"title":"AI Resume Scoring","description":"Scores candidates 0-100 against your exact job description criteria."},{"title":"Bias Detection","description":"Flags potentially biased language in job postings and screens for fair evaluation."},{"title":"Interview Question Generator","description":"Generates role-specific interview questions for each shortlisted candidate."}]',
  to_jsonb(ARRAY['Drastically reduces screening time','Bias detection is a standout feature','Clean candidate comparison view']),
  to_jsonb(ARRAY['Requires clean resume formatting','Integration with some ATS systems is manual']),
  'HR teams and recruiters handling high-volume hiring for technical and non-technical roles.',
  '[{"step":1,"title":"Upload Job Description","description":"Paste or upload your JD to set the scoring rubric."},{"step":2,"title":"Batch Upload Resumes","description":"Upload resumes in bulk (PDF, DOCX) or connect your ATS integration."},{"step":3,"title":"Review Rankings","description":"Review the AI-generated scorecard and candidate summary for each applicant."},{"step":4,"title":"Export Shortlist","description":"Export top candidates to your ATS or share the shortlist with hiring managers."}]',
  '{"metric":"8 hours/hire saved","description":"Reduced average time-to-shortlist from 3 days to 4 hours.","author":"Priya Sharma","role":"Head of Talent, GrowthCo"}'
),
