  'MarketMind generates SEO-optimized blog content, social copy, and ad creative — all from a single keyword or brief.',
  'MarketMind is the content marketing team''s secret weapon. Input a keyword, target audience, and tone — MarketMind produces a full, SEO-structured blog post with meta description, header tags, and internal link suggestions. Includes a brand voice training tool.',
  'https://marketmind.example.com',
  ARRAY['Content Generation','SEO','Social Media'],
  'marketing',
  'Paid',
  1,
  4.7, 2100, true, 'active', true,
  '[{"title":"Brand Voice Training","description":"Train MarketMind on your existing content to match your unique tone."},{"title":"SEO Brief Analyzer","description":"Ingests top-ranking competitor articles and builds a content brief to outrank them."},{"title":"Content Calendar","description":"AI-suggested publishing schedule based on your keyword strategy."}]',
  to_jsonb(ARRAY['Extremely fast content production','Strong SEO optimization built-in','Multi-format output (blog, social, email)']),
  to_jsonb(ARRAY['Requires human editing for technical topics','Brand voice training takes initial setup time']),
  'Content marketers and SEO teams producing high-volume content across multiple channels.',
  '[{"step":1,"title":"Set Brand Voice","description":"Upload 5-10 pieces of your existing content to train MarketMind on your brand tone."},{"step":2,"title":"Research Keywords","description":"Enter target keywords; MarketMind analyzes SERPs and suggests a content angle."},{"step":3,"title":"Generate Draft","description":"Generate a full draft with one click. Review the AI outline first for best results."},{"step":4,"title":"Publish","description":"Export to WordPress, Webflow, or your CMS via native integrations."}]',
  '{"metric":"20 articles/month increase","description":"Increased content output from 5 to 25 articles per month with the same 2-person team.","author":"Lisa Park","role":"Content Director, ScaleUp Inc."}'
