  'https://ui-avatars.com/api/?name=ForecastPro&background=6366f1&color=fff&bold=true',
  'AI-powered financial modeling and forecasting for modern finance teams.',
  'ForecastPro connects to your financial data and generates dynamic models, variance analysis, and forecasts automatically.',
  'ForecastPro replaces hours of manual spreadsheet work with AI-driven financial models. Connect your accounting system, ERP, or raw CSVs and get instant P&L projections, cash flow forecasts, and scenario analysis — all in a collaborative workspace.',
  'https://forecastpro.example.com',
  ARRAY['Financial Modeling','Forecasting','FP&A'],
  'finance',
  'Contact',
  7,
  4.5, 150, true, 'active', false,
  '[{"title":"Scenario Modeling","description":"Build best/base/worst case scenarios with a single slider."},{"title":"Variance Analysis","description":"Automatically flags budget vs actual variances with root-cause summaries."},{"title":"ERP Integration","description":"Native connectors for QuickBooks, Netsuite, Xero, and SAP."}]',
  to_jsonb(ARRAY['Eliminates manual model building','Excellent scenario analysis tools','Strong audit trail']),
  to_jsonb(ARRAY['High price point for SMBs','Steep learning curve for non-finance users','Contact-only pricing lacks transparency']),
  'FP&A teams and CFOs at Series B+ companies managing complex multi-entity finances.',
  '[{"step":1,"title":"Connect Data Source","description":"Authorize ForecastPro to read from your accounting system or upload a chart of accounts CSV."},{"step":2,"title":"Map Accounts","description":"Use the AI-assisted account mapping wizard to classify your P&L and Balance Sheet line items."},{"step":3,"title":"Build Base Model","description":"ForecastPro auto-generates a 12-month rolling forecast from historical data."},{"step":4,"title":"Run Scenarios","description":"Use the Scenario Builder to stress-test the model against different growth assumptions."}]',
  '{"metric":"40 hours/month saved","description":"Eliminated manual monthly close model rebuild, freeing the FP&A team for strategic analysis.","author":"David Kim","role":"CFO, NovaCorp"}'
),
(
  'a1b2c3d4-0006-0006-0006-000000000006',
