  'https://ui-avatars.com/api/?name=UserVoice&background=ec4899&color=fff&bold=true',
  'Turn thousands of user feedback signals into product decisions in minutes.',
  'UserVoice AI aggregates feedback from all channels and uses NLP to surface the themes, sentiment, and feature requests driving your roadmap.',
  'UserVoice AI connects to your support tickets, app reviews, NPS surveys, and sales call transcripts. Its AI clusters feedback by theme, assigns sentiment scores, and links each insight directly to your product roadmap — so you always know what to build next.',
  'https://uservoice.example.com',
  ARRAY['User Feedback','Product Analytics','NLP'],
  'product',
  'Freemium',
  4,
  4.8, 430, true, 'active', false,
  '[{"title":"Omnichannel Ingestion","description":"Connects to Intercom, Zendesk, App Store, G2, Slack, and sales call tools."},{"title":"Theme Clustering","description":"AI automatically groups feedback into themes and sub-themes."},{"title":"Roadmap Integration","description":"Push insights directly to Linear, Jira, or Productboard."}]',
  to_jsonb(ARRAY['Saves enormous time on feedback synthesis','Excellent integrations ecosystem','Clear visual theme explorer']),
  to_jsonb(ARRAY['AI theme naming can be vague','Free tier limited to 3 data sources']),
  'Product Managers and UX Researchers managing feedback at scale across multiple channels.',
  '[{"step":1,"title":"Connect Sources","description":"Authorize at least 2 feedback sources (e.g., Zendesk + App Store reviews)."},{"step":2,"title":"Run First Analysis","description":"Click Analyze to let UserVoice AI process and cluster your first 1,000 feedback items."},{"step":3,"title":"Review Themes","description":"Explore the Theme Explorer to validate and rename AI-generated clusters."},{"step":4,"title":"Export to Roadmap","description":"Push top themes directly to your roadmap tool as Epics or Feature requests."}]',
  '{"metric":"12 hours/sprint saved","description":"Eliminated the manual feedback synthesis session before each sprint planning.","author":"Amy Tran","role":"Head of Product, AppCo"}'
),
(
  'a1b2c3d4-0007-0007-0007-000000000007',
