  'https://ui-avatars.com/api/?name=LinkedFlow&background=0077b5&color=fff&bold=true',
  'Automate LinkedIn outreach without losing the personal touch.',
  'LinkedFlow AI writes personalized LinkedIn connection messages and follow-ups based on each prospect''s profile, posts, and company news.',
  'LinkedFlow AI integrates with LinkedIn Sales Navigator to identify, score, and engage prospects at scale. Every message is written by AI to reference specific details from the prospect''s profile — making automation feel genuinely personal.',
  'https://linkedflow.example.com',
  ARRAY['LinkedIn Automation','Social Selling','Lead Generation'],
  'sales',
  'Paid',
  3,
  4.8, 2100, true, 'active', true,
  '[{"title":"Profile-Aware Messaging","description":"References prospect''s recent posts, career history, and company news in every message."},{"title":"Campaign Analytics","description":"Full funnel view: connection rate, reply rate, meeting booked rate."},{"title":"A/B Testing","description":"Test 3 message variants simultaneously to optimize performance."}]',
  to_jsonb(ARRAY['Messages feel genuinely personal','Strong analytics dashboard','Easy LinkedIn Sales Navigator integration']),
  to_jsonb(ARRAY['LinkedIn API rate limits can slow campaigns','Requires Sales Navigator subscription']),
  'B2B sales teams using LinkedIn as their primary prospecting channel.',
  '[{"step":1,"title":"Connect LinkedIn","description":"Authorize LinkedFlow with your LinkedIn Sales Navigator account."},{"step":2,"title":"Build Prospect List","description":"Use Sales Navigator filters to create a target list of 100-500 prospects."},{"step":3,"title":"Create Campaign","description":"Define your outreach sequence (connection request + 3 follow-ups). LinkedFlow AI writes each message."},{"step":4,"title":"Launch & Optimize","description":"Launch the campaign and use A/B test results to improve message performance weekly."}]',
