  'https://reachoutgpt.example.com',
  ARRAY['Cold Email','Personalization','Email Automation'],
  'marketing',
  'Freemium',
  2,
  4.2, 850, false, 'active', false,
  '[{"title":"One-Click Research","description":"Scrapes LinkedIn, company website, and news to build a prospect dossier in seconds."},{"title":"Bulk Processing","description":"Process a CSV of 500 prospects in under 10 minutes."},{"title":"CRM Push","description":"Push personalized icebreakers directly into Outreach, Salesloft, or HubSpot fields."}]',
  to_jsonb(ARRAY['Massive time saver for personalization','Output quality is consistently high','Bulk processing is fast']),
  to_jsonb(ARRAY['Free tier limited to 20 icebreakers/month','Occasional hallucinations on less-known prospects']),
  'Marketing and sales teams running high-volume cold email campaigns.',
